$filters=['student'=>trim((string)($_GET['student']??'')),'academic_year'=>trim((string)($_GET['academic_year']??'')),'semester'=>(string)($_GET['semester']??''),'status'=>(string)($_GET['status']??'')];$where=[];$params=[];
if($filters['student']!==''){$where[]='(s.student_number LIKE ? OR s.full_name LIKE ?)';$params[]='%'.$filters['student'].'%';$params[]='%'.$filters['student'].'%';}
if(preg_match('/^\d{4}-\d{4}$/',$filters['academic_year'])){$where[]='b.academic_year=?';$params[]=$filters['academic_year'];}else{$filters['academic_year']='';}
