$sqlWhere=$where?' WHERE '.implode(' AND ',$where):'';$count=$pdo->prepare('SELECT COUNT(*) FROM billing b JOIN students s ON s.student_id=b.student_id'.$sqlWhere);$count->execute($params);$total=(int)$count->fetchColumn();$billingPages=max(1,(int)ceil($total/$size));$billingPage=min($billingPage,$billingPages);$offset=($billingPage-1)*$size;
$q=$pdo->prepare('SELECT b.billing_id,b.billing_type,b.academic_year,b.semester,b.total_amount,b.remaining_balance,b.billing_status,b.created_at,s.student_number,s.full_name FROM billing b JOIN students s ON s.student_id=b.student_id'.$sqlWhere.' ORDER BY b.created_at DESC,b.billing_id DESC LIMIT ? OFFSET ?');foreach($params as $i=>$value)$q->bindValue($i+1,$value);$q->bindValue(count($params)+1,$size,PDO::PARAM_INT);$q->bindValue(count($params)+2,$offset,PDO::PARAM_INT);$q->execute();$billingList=$q->fetchAll(PDO::FETCH_ASSOC);
