document.addEventListener('DOMContentLoaded',()=>{const footer=document.querySelector('section.payment-operational-table .card-footer');if(!footer)return;const page=<?= (int)$billingPage ?>,pages=<?= (int)$billingPages ?>,total=<?= (int)$total ?>,size=<?= (int)$size ?>,start=total?((page-1)*size)+1:0,end=Math.min(page*size,total),go=n=>{const url=new URL(window.location.href);url.searchParams.set('billing_page',n);window.location.href=url.toString();};const from=Math.max(1,page-1),to=Math.min(pages,page+1);let buttons=page>1?`<button class="btn btn-sm btn-outline-secondary me-1" data-page="${page-1}">‹</button>`:'<button class="btn btn-sm btn-outline-secondary me-1" disabled>‹</button>';for(let n=from;n<=to;n++)buttons+=`<button class="btn btn-sm ${n===page?'btn-primary':'btn-outline-secondary'} me-1" data-page="${n}">${n}</button>`;buttons+=page<pages?`<button class="btn btn-sm btn-outline-secondary" data-page="${page+1}">›</button>`:'<button class="btn btn-sm btn-outline-secondary" disabled>›</button>';footer.innerHTML=`<small class="text-muted">Showing <strong>${start}</strong> to <strong>${end}</strong> of <strong>${total}</strong> entries</small><div>${buttons}</div>`;footer.querySelectorAll('[data-page]').forEach(button=>button.onclick=()=>go(Number(button.dataset.page)));});
